#define SH_SCHOOL_ROOF_MONSTER_CALLBACK 9
static void roof_monster_book(ShTown *town, ShSavegame *save, const ShInputState *input, float dt)
{
    town->school.image = NULL;

    enum {
        EventState_BookFirstTime = 3,
        EventState_BookAgain     = 6
    };

    switch (town->step)
    {
        case 0:
            (town->controls_locked = true);
            step_set(town, town->step + 1);
        /* fall through */

        case 1:
            step_set(town, town->step + 1);
            break;

        case 2:
            step_set(town, sh_save_event_get(save, 116) ? EventState_BookAgain : EventState_BookFirstTime);
            break;

        case 3:
            card_message(town, input, 15); 
            break;

        case 4:
            ladder_wait(town, dt, 2457);
            break;

        case 5:
            card_message(town, input, 16); 
            break;

        case EventState_BookAgain:
            (town->school.next_image = "LMONSTER.TIM");
            ladder_fade(town, 0, true, 0);
            step_set(town, town->step + 1);
        /* fall through */

        case 7:
            step_set(town, town->step + 1);
            break;

        case 8:
            ladder_fade(town, 1, true, 0);
            break;

        case 9:
            (town->school.image = town->school.next_image);
            ladder_fade(town, 2, false, 0);
            break;

        case 10:
            (town->school.image = town->school.next_image);
            card_message(town, input, 17); 
            break;

        case 11:
            (town->school.image = town->school.next_image);
            ladder_fade(town, 2, true, 0);
            break;

        default:
            
            ladder_unfreeze(town);
            finish(town);

            sh_save_event_set(save, 116);
            ladder_fade(town, 0, false, 0);
            break;
    }
}
